      responsive: true,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          callbacks: {
            label: ctx => `$${ctx.parsed.y.toFixed(2)}`
          }
        },
        annotation: {}
      },
      scales: {
        x: {
          ticks: {
            maxTicksLimit: 14,
