// =============================================
// ANNUAL TABLE
// =============================================
(function() {
  const tbody = document.getElementById('annual-table-body');
  const best = Math.max(...annualData.map(d => d.ret));
  const worst = Math.min(...annualData.map(d => d.ret));

  annualData.forEach(d => {
    const tr = document.createElement('tr');
    if (d.ret === best) tr.className = 'year-best';
    if (d.ret === worst) tr.className = 'year-worst';

    const retClass = d.ret >= 0 ? 'pos' : 'neg';
    const retStr = (d.ret >= 0 ? '+' : '') + d.ret.toFixed(2) + '%';
    const volStr = (d.annVol >= 40 ? '🔴 ' : d.annVol >= 28 ? '🟡 ' : '🟢 ') + d.annVol.toFixed(1) + '%';

    tr.innerHTML = `
      <td><strong>${d.year}</strong>${d.ret === best ? ' <span class="badge-pill pill-green">Best</span>' : d.ret === worst ? ' <span class="badge-pill pill-red">Worst</span>' : ''}</td>
      <td class="num">$${d.start.toFixed(2)}</td>
      <td class="num">$${d.end.toFixed(2)}</td>
      <td class="num ${retClass}">${retStr}</td>
      <td class="num">${(d.vol / 1e6).toFixed(2)}M</td>
      <td class="num">$${d.high.toFixed(2)}</td>
      <td class="num">$${d.low.toFixed(2)}</td>
      <td class="num">${volStr}</td>
    `;
    tbody.appendChild(tr);
  });
})();
</script>
